import React, {useMemo, useState} from 'react';
import {FlatList, TextInput, View, Text} from 'react-native';

export default function ContactsList({data}) {
  const [q, setQ] = useState('');
  const filtered = useMemo(() => data.filter(d => d.name.includes(q)), [data, q]);
  const renderItem = React.useCallback(({item}) => <Text>{item.name}</Text>, []);
  return (
    <FlatList
      data={filtered}
      keyExtractor={item => item.id}
      renderItem={renderItem}
      getItemLayout={(d, index) => ({length: 48, offset: 48 * index, index})}
      onRefresh={() => /* fetch */}
      refreshing={false}
      onEndReached={() => /* load more */}
      ListHeaderComponent={<TextInput value={q} onChangeText={setQ} />}
    />
  );
}
```

